CREATE TABLE IF NOT EXISTS drawing_symbol_segmentation_versions (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,geometry_version_id TEXT NOT NULL,version_number INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,output_fingerprint TEXT NOT NULL,engine_version TEXT NOT NULL,status TEXT NOT NULL,summary TEXT NOT NULL,created_by TEXT NOT NULL,superseded_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS drawing_symbol_segmentation_version_idx ON drawing_symbol_segmentation_versions(document_id,version_number);
CREATE TABLE IF NOT EXISTS drawing_symbol_cluster_candidates (id TEXT PRIMARY KEY,segmentation_version_id TEXT NOT NULL,geometry_candidate_id TEXT NOT NULL,approved_row_id TEXT NOT NULL,cluster_number INTEGER NOT NULL,bounding_box TEXT NOT NULL,fragments TEXT NOT NULL,original_fragments TEXT NOT NULL,fragment_count INTEGER NOT NULL,geometry_signature TEXT NOT NULL,detection_basis TEXT NOT NULL,confidence INTEGER NOT NULL,exclusion_reason TEXT,review_status TEXT NOT NULL DEFAULT 'Needs Review',reviewed_by TEXT,reviewed_at TEXT,review_reason TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS drawing_symbol_cluster_number_idx ON drawing_symbol_cluster_candidates(segmentation_version_id,geometry_candidate_id,cluster_number);
CREATE TABLE IF NOT EXISTS drawing_symbol_cluster_events (id TEXT PRIMARY KEY,project_id TEXT NOT NULL,document_id TEXT NOT NULL,segmentation_version_id TEXT NOT NULL,cluster_id TEXT NOT NULL,action TEXT NOT NULL,previous_value TEXT NOT NULL,new_value TEXT NOT NULL,reason TEXT NOT NULL,actor_user_id TEXT NOT NULL,request_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS drawing_symbol_cluster_event_idx ON drawing_symbol_cluster_events(cluster_id,created_at);
